// genuary, tau, textile, velvet
//
// genuary9+10

#define TAU 6.283185

#define ROTM(ang) mat2( cos( ang + TAU*vec4(0,1,-1,0)/4. ) )

#define SDFFontTex iChannel0

float getCharDist(int c, vec2 p)  // p=[(-.5,-.5)..(.5,.5)]
{
    vec2 r=vec2(textureSize(SDFFontTex,0));
    float d=textureLod(SDFFontTex,vec2(c%16,15-c/16)/16.+vec2(0,1)+clamp((p+.5)/16.,1./r,1.-1./r),0.).w-.5;
    vec2  d2=abs(p)-(.5-1./r);
    if (d2.x>0. || d2.y>0.) return d+max(d2.x,d2.y);
    return d-.02;
}

vec3 hsv2rgb(float h, float s, float v) {
    vec3 p = abs(fract(h + vec3(3,2,1)/3.) * 6. - 3.);
    return v * (1. + clamp(p - 2., -1., 0.)* s);
}

void mainImage( out vec4 fragColor, vec2 fragCoord )
{
    int lnum=4;
    int l[4]=int[4](84,65,85,32);

    vec4 col=vec4(.3,.4,.5,0);
    vec3 n=vec3(0,0,1);
    vec4 nv=texture(iChannel1,fragCoord/256.*.85)-texture(iChannel1,fragCoord/256.*.85+1./256.);
    vec4 nv2=texture(iChannel1,fragCoord*.00003*1.)
            +texture(iChannel1,fragCoord*.00003*2.)/(2.)
            +texture(iChannel1,fragCoord*.00003*4.)/(4.)
            +texture(iChannel1,fragCoord*.00003*8.)/(8.);
    fragCoord.xy+=nv.xy*2.;
    nv2/=4.;
    n=normalize(texture(iChannel1,fragCoord*ROTM(1.)*.004*vec2(-.03,3)).xyz-.5+.3*(texture(iChannel1,fragCoord*.001).xyz-.5));
    vec2 csize=vec2(20,30)*2.;
    int num=3;
    for(int i=0;i<num;i++){
        vec2 off=cos(iTime*3.+float(i)/float(num)*TAU+vec2(TAU/4.,0))*.13;
        vec2 c=fragCoord/csize+off;
        c.x+=mod(floor(c.y),2.)*.37*float(lnum);
        ivec2 ci=ivec2(c);
        vec4 ri=texelFetch(iChannel1,(ci+ivec2(13,5)*i)%256,0);
        vec4 rw=texelFetch(iChannel1,(ci/ivec2(lnum,1)+ivec2(13,5)*i)%256,0);
        int ch=l[int(ci)%lnum];
        if(ri.w<.5 && ch!=32) ch+=32;
        float d=getCharDist(ch,((fract(c)-.5)*vec2(.7,1))*ROTM(sin(iTime*10.+float(i)+ri.x*TAU)*.1));
        float mask=1.-step(.06,d);
        float st=1.-smoothstep(.0,.04,-(d-.06));
        if (ri.x>col.w && mask>.5) { col=vec4(hsv2rgb(rw.x,.75,.85-st*.65),ri.x); }
    }
    vec3 eye=normalize(vec3((fragCoord-iResolution.xy*.5)/iResolution.x,.2));
    fragColor.xyz=vec3(0)+col.xyz+.06*nv.x+.6*nv2.x+.1*sin(fragCoord.y*1.5);
    fragColor.w=1.;
}
